-- СКРИПТ СИНХРОНИЗАЦИИ ВЕРСИЙ БД DECANET
-- --------------------------------------
-- v0.016 2009-01-18
-- --------------------------------------
USE decanet;
USE decanet;

DELIMITER $$

-- существование индекса
-- DROP FUNCTION IF EXISTS decanet.INDEXEXISTS $$
DROP FUNCTION IF EXISTS INDEXEXISTS $$
CREATE FUNCTION decanet.INDEXEXISTS(IDXNAME VARCHAR(64), TBLNAME VARCHAR(64)) RETURNS BOOL
BEGIN
  RETURN EXISTS (SELECT *
                  FROM information_schema.TABLE_CONSTRAINTS T
                  WHERE TABLE_SCHEMA = 'decanet' AND
                        TABLE_NAME = TBLNAME AND
                        CONSTRAINT_NAME = IDXNAME);
END $$

-- модификация с 0.001 до 0.002
DROP PROCEDURE IF EXISTS decanet.DCVERS_0001_0002 $$
CREATE PROCEDURE decanet.DCVERS_0001_0002()
BEGIN

  ALTER TABLE decanet.student DROP COLUMN STUDENT_BUCHNO;

  ALTER TABLE decanet.SGROUP DROP COLUMN SGROUP_ACTIVE;

  ALTER TABLE decanet.CONTROL ADD COLUMN CONTROL_NAMED BOOL NOT NULL DEFAULT FALSE AFTER CONTROL_NAME;

  UPDATE decanet.CONTROL
    SET CONTROL_NAMED = TRUE
    WHERE CONTROL_ID IN (4, 5, 7, 9, 10, 12, 13);

  UPDATE decanet.STUDADD
    SET STUDENT_DESC = NULL;
END $$

-- модификация с 0.002 до 0.003
DROP PROCEDURE IF EXISTS decanet.DCVERS_0002_0003 $$
CREATE PROCEDURE decanet.DCVERS_0002_0003()
BEGIN
  REPLACE INTO PROLTYPE (PROLTYPE_ID, PROLTYPE_ABBR, PROLTYPE_NAME)
    VALUES (1, 'МедСпр', 'По состоянию здоровья'),
           (2, 'СемОбст', 'По семейным обстоятельствам');

  ALTER TABLE decanet.PROLONG ADD COLUMN PROLONG_TODATE DATE NOT NULL AFTER PROLTYPE_ID;
  ALTER TABLE decanet.student DROP COLUMN STUDSTATUS_ACTIVE;

  UPDATE decanet.document
    SET DOCUMENT_BARNO = CONCAT(FACULTET_ID, DOCUMENT_ID)
    WHERE DOCUMENT_BARNO IS NULL;

  UPDATE decanet.document
    SET DOCUMENT_TEMPFLAG = FALSE
    WHERE DOCUMENT_INDATE IS NOT NULL;

  UPDATE decanet.doctype
    SET DOCTYPE_NAME = 'Диплом'
    WHERE DOCTYPE_ID = 7;

END $$

-- модификация с 0.003 до 0.004
DROP PROCEDURE IF EXISTS decanet.DCVERS_0003_0004 $$
CREATE PROCEDURE decanet.DCVERS_0003_0004()
BEGIN
  IF NOT INDEXEXISTS('IDX_CONTINGENT_D', 'contingent') THEN
    CREATE INDEX IDX_CONTINGENT_D ON decanet.contingent(DOCUMENT_ID);
  END IF;

  INSERT INTO decanet.doctype(DOCTYPE_ID, DOCTYPE_NAME, DOCTYPE_ABBR)
    VALUES(12, 'Ведомость тем', 'ТемаВед');
END $$

-- модификация с 0.004 до 0.005
DROP PROCEDURE IF EXISTS decanet.DCVERS_0004_0005 $$
CREATE PROCEDURE decanet.DCVERS_0004_0005()
BEGIN
  -- формы обучения
  DELETE FROM decanet.eduform
    WHERE EDUFORM_ID >= 6;

  UPDATE decanet.student
    SET EDUFORM_ID = 5
    WHERE EDUFORM_ID = 3;
  DELETE FROM decanet.eduform
    WHERE EDUFORM_ID = 3;

  UPDATE decanet.eduform
    SET EDUFORM_ABBR = 'бюджет',
        EDUFORM_NAME = 'Бюджетное',
        EDUFORM_STIP = 1
    WHERE EDUFORM_ID = 1;

  UPDATE decanet.eduform
    SET EDUFORM_ABBR = 'бюджет-целевик-оплата',
        EDUFORM_NAME = 'Бюджетное целевое с оплатой',
        EDUFORM_STIP = 1
    WHERE EDUFORM_ID = 2;

  UPDATE decanet.eduform
    SET EDUFORM_ABBR = 'вне бюджет',
        EDUFORM_NAME = 'Внебюджетное',
        EDUFORM_STIP = 0
    WHERE EDUFORM_ID = 4;

  UPDATE decanet.eduform
    SET EDUFORM_ABBR = 'бюджет-целевик',
        EDUFORM_NAME = 'Бюджетное целевое',
        EDUFORM_STIP = 1
    WHERE EDUFORM_ID = 5;

  -- отделения
  UPDATE decanet.division
    SET DIVISION_ABBR = '250201',
        DIVISION_NAME = '250201 Лесное хозяйство'
    WHERE DIVISION_ID = 1;

  UPDATE decanet.division
    SET DIVISION_ABBR = '250201 (3 года)',
        DIVISION_NAME = '250201 Лесное хозяйство (3 года)'
    WHERE DIVISION_ID = 2;

  UPDATE decanet.division
    SET DIVISION_ABBR = '250100',
        DIVISION_NAME = '250100 Лесное дело'
    WHERE DIVISION_ID = 3;

  UPDATE decanet.division
    SET DIVISION_ABBR = '250203',
        DIVISION_NAME = '250203 Садово-парковое и ландшафтное строительство'
    WHERE DIVISION_ID = 4;

  UPDATE decanet.division
    SET DIVISION_ABBR = '250203 (очно-заочное)',
        DIVISION_NAME = '250203 Садово-парковое и ландшафтное строительство (очно-заочное)'
    WHERE DIVISION_ID = 5;

  UPDATE decanet.direction
    SET DIRECTION_NAME = 'Лесное дело'
    WHERE DIRECTION_ID = 2;

  INSERT INTO decanet.direction (DIRECTION_ID, DIRECTION_CODE, DIRECTION_NAME)
    VALUES (3, 120302, 'Земельный кадастр');

  INSERT INTO decanet.division (DIVISION_ID, FACULTET_ID, EDUTYPE_ID, DIRECTION_ID, SPECIALITY_ID, SUBSPEC_ID,
                                DIVISION_ABBR, DIVISION_NAME,
                                DIVISION_UYEAR, DIVISION_HALFUYEAR,
                                DIVISION_ALGNO, DIVISION_DESC)
    VALUES (6, 1, 3, 1, 2, NULL, '250203 (3 года)', '250203 Садово-парковое и ландшафтное строительство (3 года)', 9, 2, 1, NULL),
           (7, 1, 3, 3, NULL, NULL, '120302', '120302 Земельный кадастр', 9, 2, 1, NULL),
           (8, 1, 3, 1, 1, NULL, '250201 (магистратура)', '250201 Лесное хозяйство (магистратура)', 9, 2, 1, NULL),
           (9, 1, 3, 1, 2, NULL, '250203 (магистратура)', '250203 Садово-парковое и ландшафтное строительство (магистратура)', 9, 2, 1, NULL);
END $$



-- модификация с 0.005 до 0.006
DROP PROCEDURE IF EXISTS decanet.DCVERS_0005_0006 $$
CREATE PROCEDURE decanet.DCVERS_0005_0006()
BEGIN
  -- Экономика отрасли vs Экономика
--  INSERT INTO decanet.subj(SUBJ_ID, SUBJ_ABBR, SUBJ_NAME)
--    VALUES (NULL, 'ЭкОтр', 'Экономика отрасли');

--  SET @SID = Last_Insert_ID();

  SET @SID = 194;

  UPDATE decanet.mprogsubj
    SET SUBJ_ID = @SID
    WHERE MAINPROG_ID = 589;

  -- ДДиЦ vs Д
  UPDATE decanet.progdoc D LEFT JOIN
         decanet.persprog P USING (PERSPROG_ID) LEFT JOIN
         decanet.acad A USING (PERSPROG_ID) LEFT JOIN
         decanet.persprog P1 ON P1.mainprog_ID = 199 AND P1.student_ID = P.student_ID
    SET D.PERSPROG_ID = P1.PERSPROG_ID,
        A.PERSPROG_ID = P1.PERSPROG_ID
    WHERE P.mainprog_ID = 200;

  SET FOREIGN_KEY_CHECKS = 0;
  -- multidelete syntax
  DELETE decanet.ACAD, decanet.document, decanet.PROGDOC, decanet.PERSPROG, decanet.MPROGSUBJ, decanet.mainprog
    FROM decanet.mainprog LEFT JOIN
         decanet.MPROGSUBJ USING (MAINPROG_ID) LEFT JOIN
         decanet.PERSPROG USING (MAINPROG_ID) LEFT JOIN
         decanet.PROGDOC USING (PERSPROG_ID) LEFT JOIN
         decanet.document USING (DOCUMENT_ID) LEFT JOIN
         decanet.ACAD USING (PERSPROG_ID, DOCUMENT_ID)
    WHERE MAINPROG_ID = 200;
  SET FOREIGN_KEY_CHECKS = 1;

  UPDATE decanet.mprogsubj
    SET SUBJ_ID = 20
    WHERE MAINPROG_ID = 199;

  -- ИГ
