  UPDATE decanet.mainprog M LEFT JOIN
         decanet.MPROGSUBJ J USING (MAINPROG_ID) LEFT JOIN
         decanet.DSESSION E USING(DSESSION_ID)
    SET M.CONTROL_ID = 3
    WHERE J.SUBJ_ID = 45 AND E.SEMESTR = 1 AND M.CONTROL_ID = 2;

  UPDATE decanet.acad A LEFT JOIN
         decanet.persprog P USING (PERSPROG_ID) LEFT JOIN
         decanet.student S USING (STUDENT_ID) LEFT JOIN
         decanet.ttIG1 I ON I.LN = S.student_PERSNO LEFT JOIN
         decanet.result R ON R.RESULT_INT = I.MARK LEFT JOIN
         decanet.mainprog M USING (MAINPROG_ID) LEFT JOIN
         decanet.MPROGSUBJ J USING (MAINPROG_ID) LEFT JOIN
         decanet.DSESSION E USING (DSESSION_ID)
    SET A.RESULT_ID = R.RESULT_ID
  WHERE J.SUBJ_ID = 45 AND E.SEMESTR = 1 AND M.CONTROL_ID = 3 AND I.LN IS NOT NULL;

  DROP TABLE decanet.ttIG1;

  UPDATE decanet.mainprog M LEFT JOIN
         decanet.MPROGSUBJ J USING (MAINPROG_ID) LEFT JOIN
         decanet.DSESSION E USING(DSESSION_ID) LEFT JOIN
         decanet.persprog P USING (MAINPROG_ID) LEFT JOIN
         decanet.acad A USING (PERSPROG_ID) LEFT JOIN
         decanet.progdoc R USING (PERSPROG_ID) LEFT JOIN
         decanet.document D ON R.document_ID = D.document_ID
  SET D.document_TEMPFLAG = 1
  WHERE J.SUBJ_ID = 45 AND E.SEMESTR = 1 AND M.CONTROL_ID = 3 AND A.RESULT_ID IN (5,6) AND D.doctype_ID = 2;

  DELETE decanet.acad
    FROM decanet.acad LEFT JOIN
         decanet.persprog USING (PERSPROG_ID) LEFT JOIN
         decanet.mainprog USING (MAINPROG_ID) LEFT JOIN
         decanet.MPROGSUBJ USING (MAINPROG_ID) LEFT JOIN
         decanet.DSESSION USING(DSESSION_ID)
  WHERE SUBJ_ID = 45 AND SEMESTR = 1 AND CONTROL_ID = 3 AND RESULT_ID IN (5,6);

END $$


