  -- адаптированный к факультету состав дисциплин в разделе стандарта
  CREATE TABLE decanet.gsubj (GSUBJ_ID INT NOT NULL AUTO_INCREMENT,
                              CONSTRAINT PK_GSUBJ PRIMARY KEY (GSUBJ_ID),
                              FACULTET_ID INT NOT NULL,
                              CONSTRAINT FK_GSUBJ_FACULTET FOREIGN KEY (FACULTET_ID) REFERENCES facultet(FACULTET_ID) ON DELETE NO ACTION ON UPDATE NO ACTION,
                              GOS_ID INT NOT NULL,
                              CONSTRAINT FK_GSUBJ_GOS FOREIGN KEY (GOS_ID) REFERENCES gos(GOS_ID) ON DELETE NO ACTION ON UPDATE NO ACTION,
                              SUBJ_ID INT NOT NULL,
                              CONSTRAINT FK_GSUBJ_SUBJ FOREIGN KEY (SUBJ_ID) REFERENCES subj(SUBJ_ID) ON DELETE NO ACTION ON UPDATE NO ACTION,
                              GSUBJ_CODE VARCHAR(25) NOT NULL
  ) /*!ENGINE=INNODB*/;

  IF NOT INDEXEXISTS('UIDX_GSUBJ', 'gsubj') THEN
    CREATE UNIQUE INDEX UIDX_GSUBJ ON decanet.gsubj(FACULTET_ID, GOS_ID, SUBJ_ID);
  END IF;

  -- удаляем старый механизм специальностей
  ALTER TABLE decanet.division DROP FOREIGN KEY FK_DIVISION_DIRECTION;
  ALTER TABLE decanet.division DROP COLUMN DIRECTION_ID;
  ALTER TABLE decanet.division DROP FOREIGN KEY FK_DIVISION_SPECIALITY;
  ALTER TABLE decanet.division DROP COLUMN SPECIALITY_ID;

  ALTER TABLE decanet.subspec DROP FOREIGN KEY FK_SUBSPEC_SPECIALITY;
  ALTER TABLE decanet.subspec DROP COLUMN SPECIALITY_ID;
  ALTER TABLE decanet.subspec ADD COLUMN GOSTITLE_ID INT NOT NULL AFTER SUBSPEC_ID;
  ALTER TABLE decanet.subspec ADD CONSTRAINT FK_SUBSPEC_GOSTITLE FOREIGN KEY (GOSTITLE_ID) REFERENCES gostitle(GOSTITLE_ID) ON DELETE NO ACTION ON UPDATE NO ACTION;

  DROP TABLE decanet.speciality;
  DROP TABLE decanet.direction;

  -- назначение отделениям стандарта
  ALTER TABLE decanet.division ADD COLUMN GOSTITLE_ID INT NOT NULL AFTER FACULTET_ID;
  UPDATE decanet.division
    SET GOSTITLE_ID = 1
    WHERE DIVISION_ID = 7;
  UPDATE decanet.division
    SET GOSTITLE_ID = 2
    WHERE DIVISION_ID = 3;
  UPDATE decanet.division
    SET GOSTITLE_ID = 3
    WHERE DIVISION_ID IN (1, 2, 8);
  UPDATE decanet.division
    SET GOSTITLE_ID = 4
    WHERE DIVISION_ID IN (4, 5, 6, 9);
  ALTER TABLE decanet.division ADD CONSTRAINT FK_DIVISION_GOSTITLE FOREIGN KEY (GOSTITLE_ID) REFERENCES gostitle(GOSTITLE_ID) ON DELETE NO ACTION ON UPDATE NO ACTION;

  -- здесь адаптируем подсистему к операциям восстановить / перевести
  -- mainprog
  ALTER TABLE decanet.mainprog ADD COLUMN MAINPROG_HIDFLAG BOOL NOT NULL DEFAULT FALSE AFTER VOLUME;
  ALTER TABLE decanet.mainprog DROP COLUMN VOLUMEDOC;

  -- persprog - чистим дубли
  CREATE TABLE decanet.wrk_persprog AS
    SELECT MIN(P.PERSPROG_ID) AS PERSPROG_ID, P.student_ID, D.SEMESTR, J.SUBJ_ID, M.CONTROL_ID, P.VOLUME
      FROM decanet.persprog P LEFT JOIN
           decanet.mainprog M USING (MAINPROG_ID) LEFT JOIN
           decanet.mprogsubj J USING (MPROGSUBJ_ID) LEFT JOIN
           decanet.dsession D USING (DSESSION_ID)
      GROUP BY P.student_ID, D.SEMESTR, J.SUBJ_ID, M.CONTROL_ID;

  CREATE UNIQUE INDEX UIDX_WRK_PERSPROG ON decanet.wrk_persprog(PERSPROG_ID);

  SET FOREIGN_KEY_CHECKS = 0;

  DELETE decanet.persprog
    FROM decanet.persprog LEFT JOIN
         decanet.wrk_persprog USING (PERSPROG_ID)
    WHERE PERSPROG_ID IS NULL;

  DROP TABLE wrk_persprog;

  DELETE decanet.acad
    FROM decanet.acad LEFT JOIN
         decanet.persprog USING (PERSPROG_ID)
    WHERE PERSPROG_ID IS NULL;

  DELETE decanet.progdoc
    FROM decanet.progdoc LEFT JOIN
         decanet.persprog USING (PERSPROG_ID)
    WHERE PERSPROG_ID IS NULL;

  DELETE decanet.persname
    FROM decanet.persname LEFT JOIN
         decanet.persprog USING (PERSPROG_ID)
    WHERE PERSPROG_ID IS NULL;

  SET FOREIGN_KEY_CHECKS = 1;

  -- заплатка
  DELETE FROM decanet.persprog WHERE PERSPROG_ID = 357166;

  -- перезачет оценок ранее восстановленных студентов
  UPDATE decanet.student S LEFT JOIN
         decanet.sgroup G USING (SGROUP_ID) LEFT JOIN
         decanet.stream R USING (STREAM_ID) LEFT JOIN
         decanet.dsession E USING (STREAM_ID) LEFT JOIN
         decanet.mainprog M USING (DSESSION_ID) LEFT JOIN
         decanet.mprogsubj J USING (MAINPROG_ID) LEFT JOIN
         decanet.persprog P USING (STUDENT_ID) LEFT JOIN
         decanet.mprogsubj Q ON Q.MPROGSUBJ_ID = P.MPROGSUBJ_ID LEFT JOIN
         decanet.mainprog N ON N.mainprog_ID = P.mainprog_ID LEFT JOIN
         decanet.dsession I ON I.DSESSION_ID = N.DSESSION_ID
    SET P.mainprog_ID = IFNULL(M.mainprog_ID, P.mainprog_ID)
    WHERE E.DSESSION_ID <> I.DSESSION_ID AND
          Q.SUBJ_ID = J.SUBJ_ID AND
          N.CONTROL_ID = M.CONTROL_ID AND
          E.SEMESTR = I.SEMESTR;

  -- студенты - группы
  CREATE TABLE decanet.studsgrp (STUDSGRP_ID INT NOT NULL AUTO_INCREMENT,
                                 CONSTRAINT PK_STUDSGRP PRIMARY KEY (STUDSGRP_ID),
                                 -- для уникальности обучения на отделении
                                 DIVISION_ID INT NOT NULL,
                                 CONSTRAINT FK_STUDSGRP_DIVISION FOREIGN KEY (DIVISION_ID) REFERENCES division(DIVISION_ID) ON DELETE NO ACTION ON UPDATE NO ACTION,
                                 SGROUP_ID INT NOT NULL,
                                 CONSTRAINT FK_STUDSGRP_SGROUP FOREIGN KEY (SGROUP_ID) REFERENCES sgroup(SGROUP_ID) ON DELETE NO ACTION ON UPDATE NO ACTION,
                                 STUDENT_ID INT NOT NULL,
                                 CONSTRAINT FK_STUDSGRP_STUDENT FOREIGN KEY (STUDENT_ID) REFERENCES student(STUDENT_ID) ON DELETE NO ACTION ON UPDATE NO ACTION,
                                 EDUFORM_ID INT NOT NULL,
                                 CONSTRAINT FK_STUDSGRP_EDUFORM FOREIGN KEY (EDUFORM_ID) REFERENCES eduform(EDUFORM_ID) ON DELETE NO ACTION ON UPDATE NO ACTION
  ) /*!ENGINE=INNODB*/;

  IF NOT INDEXEXISTS('UIDX_STUDSGRP', 'studsgrp') THEN
    CREATE UNIQUE INDEX UIDX_STUDSGRP ON decanet.studsgrp(DIVISION_ID, STUDENT_ID);
  END IF;

  -- !!! ДЛЯ ОТЛАДКИ ИНТЕРФЕЙСА - ПОТОМ УБРАТЬ !!!
  --  ALTER TABLE decanet.studsgrp AUTO_INCREMENT = 100000;

  INSERT INTO decanet.studsgrp (STUDSGRP_ID, DIVISION_ID, SGROUP_ID, STUDENT_ID, EDUFORM_ID)
    SELECT NULL, R.DIVISION_ID, S.SGROUP_ID, S.student_ID, S.EDUFORM_ID
      FROM decanet.student S LEFT JOIN
           decanet.sgroup G USING (SGROUP_ID) LEFT JOIN
           decanet.stream R USING (STREAM_ID);

  ALTER TABLE decanet.student DROP FOREIGN KEY FK_STUDENT_SGROUP;
  ALTER TABLE decanet.student DROP COLUMN SGROUP_ID;
  ALTER TABLE decanet.student DROP FOREIGN KEY FK_STUDENT_EDUFORM;
  ALTER TABLE decanet.student DROP COLUMN EDUFORM_ID;

  ALTER TABLE decanet.persprog DROP COLUMN VOLUMEDOC;
  ALTER TABLE decanet.persprog ADD COLUMN STUDSGRP_ID INT NOT NULL AFTER PERSPROG_ID;
  UPDATE decanet.persprog P LEFT JOIN
         decanet.studsgrp SG USING (STUDENT_ID)
      SET P.STUDSGRP_ID = SG.STUDSGRP_ID;
  ALTER TABLE decanet.persprog ADD CONSTRAINT FK_PERSPROG_STUDSGRP FOREIGN KEY (STUDSGRP_ID) REFERENCES studsgrp(STUDSGRP_ID) ON DELETE NO ACTION ON UPDATE NO ACTION;

  ALTER TABLE decanet.persprog DROP FOREIGN KEY FK_PERSPROG_STUDENT;
  ALTER TABLE decanet.persprog DROP INDEX IDX_PPKEY;
  ALTER TABLE decanet.persprog DROP FOREIGN KEY FK_PERSPROG_MAINPROG;
  ALTER TABLE decanet.persprog DROP INDEX UIDX_PERSPROG;
  ALTER TABLE decanet.persprog DROP COLUMN STUDENT_ID;
  CREATE UNIQUE INDEX UIDX_PERSPROG ON decanet.persprog(MAINPROG_ID, STUDSGRP_ID);
  CREATE INDEX IDX_PPKEY ON decanet.persprog(MPROGSUBJ_ID, STUDSGRP_ID);
  ALTER TABLE decanet.persprog ADD CONSTRAINT FK_PERSPROG_MAINPROG FOREIGN KEY (MAINPROG_ID) REFERENCES mainprog(MAINPROG_ID) ON DELETE NO ACTION ON UPDATE NO ACTION;

  ALTER TABLE decanet.contingent ADD COLUMN STUDSGRP_ID INT NOT NULL AFTER CONTINGENT_ID;
  UPDATE decanet.contingent C LEFT JOIN
         decanet.studsgrp SG USING (STUDENT_ID)
      SET C.STUDSGRP_ID = SG.STUDSGRP_ID;
  ALTER TABLE decanet.contingent ADD CONSTRAINT FK_CONTINGENT_STUDSGRP FOREIGN KEY (STUDSGRP_ID) REFERENCES studsgrp(STUDSGRP_ID) ON DELETE NO ACTION ON UPDATE NO ACTION;

  ALTER TABLE decanet.contingent DROP FOREIGN KEY FK_CONTINGENT_STUDENT;
  ALTER TABLE decanet.contingent DROP INDEX UIDX_CONTINGENT;
  ALTER TABLE decanet.contingent DROP COLUMN STUDENT_ID;
  CREATE UNIQUE INDEX UIDX_CONTINGENT ON decanet.contingent(STUDSGRP_ID, STUDSTATUS_ID, DOCUMENT_ID);

  ALTER TABLE decanet.studdoc ADD COLUMN STUDSGRP_ID INT NOT NULL AFTER STUDDOC_ID;
  UPDATE decanet.studdoc D LEFT JOIN
         decanet.studsgrp SG USING (STUDENT_ID)
      SET D.STUDSGRP_ID = SG.STUDSGRP_ID;
  ALTER TABLE decanet.studdoc ADD CONSTRAINT FK_STUDDOC_STUDSGRP FOREIGN KEY (STUDSGRP_ID) REFERENCES studsgrp(STUDSGRP_ID) ON DELETE NO ACTION ON UPDATE NO ACTION;

  ALTER TABLE decanet.studdoc DROP FOREIGN KEY FK_STUDDOC_STUDENT;
  ALTER TABLE decanet.studdoc DROP INDEX UIDX_STUDDOC;
  ALTER TABLE decanet.studdoc DROP COLUMN STUDENT_ID;
  CREATE UNIQUE INDEX UIDX_STUDDOC ON decanet.studdoc(STUDSGRP_ID, DOCUMENT_ID);

  -- продления на STUDSGRP_ID
  ALTER TABLE decanet.prolong ADD COLUMN STUDSGRP_ID INT NOT NULL AFTER STUDENT_ID;
  UPDATE decanet.prolong P LEFT JOIN
         decanet.studsgrp SG USING (STUDENT_ID)
      SET P.STUDSGRP_ID = SG.STUDSGRP_ID;
  ALTER TABLE decanet.prolong DROP FOREIGN KEY FK_PROLONG_STUDENT;
  ALTER TABLE decanet.prolong DROP FOREIGN KEY FK_PROLONG_PROLTYPE;
  ALTER TABLE decanet.prolong DROP FOREIGN KEY FK_PROLONG_DSESSION;
  ALTER TABLE decanet.prolong DROP INDEX UIDX_PROLONG;
  ALTER TABLE decanet.prolong DROP COLUMN STUDENT_ID;
  ALTER TABLE decanet.prolong ADD CONSTRAINT FK_PROLONG_STUDSGRP FOREIGN KEY (STUDSGRP_ID) REFERENCES studsgrp(STUDSGRP_ID) ON DELETE NO ACTION ON UPDATE NO ACTION;
  ALTER TABLE decanet.prolong ADD CONSTRAINT FK_PROLONG_PROLTYPE FOREIGN KEY (PROLTYPE_ID) REFERENCES proltype(PROLTYPE_ID) ON DELETE NO ACTION ON UPDATE NO ACTION;
  ALTER TABLE decanet.prolong ADD CONSTRAINT FK_PROLONG_DSESSION FOREIGN KEY (DSESSION_ID) REFERENCES dsession(DSESSION_ID) ON DELETE NO ACTION ON UPDATE NO ACTION;
  CREATE UNIQUE INDEX UIDX_PROLONG ON decanet.prolong(DSESSION_ID, STUDSGRP_ID);

END $$

-- модификация с 0.007 до 0.008
DROP PROCEDURE IF EXISTS decanet.DCVERS_0007_0008 $$
CREATE PROCEDURE decanet.DCVERS_0007_0008()
BEGIN

  -- причесываем группы в садово-парковом...
  UPDATE decanet.studsgrp
    SET SGROUP_ID = 101
    WHERE SGROUP_ID IN (106, 61);

  UPDATE decanet.studsgrp
    SET SGROUP_ID = 60
    WHERE SGROUP_ID = 104;

  DELETE
    FROM decanet.sgroup
    WHERE SGROUP_ID IN (61, 106, 104);

  ALTER TABLE decanet.school DROP COLUMN SCHOOL_BOSSFIO;
  ALTER TABLE decanet.facultet DROP COLUMN FACULTET_BOSSFIO;

END $$

-- модификация с 0.008 до 0.009
DROP PROCEDURE IF EXISTS decanet.DCVERS_0008_0009 $$
CREATE PROCEDURE decanet.DCVERS_0008_0009()
BEGIN

  -- синхронизация P.MPROGSUBJ_ID - из за ошибки автоперезачета
  UPDATE decanet.persprog P LEFT JOIN
         decanet.mprogsubj J USING (MPROGSUBJ_ID) LEFT JOIN
         decanet.mainprog M ON M.mainprog_ID = P.mainprog_ID LEFT JOIN
         decanet.mprogsubj Q ON Q.mainprog_ID = M.mainprog_ID
  SET P.MPROGSUBJ_ID = Q.MPROGSUBJ_ID
  WHERE Q.SUBJ_ID = J.SUBJ_ID AND
        P.mainprog_ID <> J.mainprog_ID;


  -- централизация физкультуры
  UPDATE decanet.mprogsubj
    SET SUBJ_ID = 205
    WHERE SUBJ_ID = 165;

  UPDATE decanet.gsubj
    SET SUBJ_ID = 205
    WHERE SUBJ_ID = 165;

  DELETE FROM decanet.subj
    WHERE SUBJ_ID = 165;

  -- лог таблица
  CREATE TABLE decanet.syslog (SYSLOG_ID INT NOT NULL AUTO_INCREMENT,
                               CONSTRAINT PK_SYSLOG PRIMARY KEY (SYSLOG_ID),
                               SYSLOG_TIMESTAMP TIMESTAMP NOT NULL,
                               DUSER_ID INT NOT NULL,
                               CONSTRAINT FK_SYSLOG_DUSER FOREIGN KEY (DUSER_ID) REFERENCES duser(DUSER_ID) ON DELETE NO ACTION ON UPDATE NO ACTION,
                               SYSLOG_IP INT NOT NULL,
                               SYSLOG_STATEMENT VARCHAR(255) NOT NULL,
                               SYSLOG_ERRNO INT NOT NULL,
                               SYSLOG_ERRDESC VARCHAR(255)
  ) /*!ENGINE=INNODB*/;

  -- профилактика дубликатов оценок (тройки)
  DELETE decanet.acad
    FROM (SELECT A.ACAD_ID, A.PERSPROG_ID, A.document_ID, X.CNT
            FROM (SELECT MAX(ACAD_ID) AS ACAD_ID, COUNT(ACAD_ID) AS CNT
                    FROM ACAD
                    WHERE RESULT_ID = 3
                    GROUP BY PERSPROG_ID HAVING COUNT(ACAD_ID) > 1) X LEFT JOIN
                 decanet.acad A USING (ACAD_ID)) Y LEFT JOIN
         decanet.acad USING (ACAD_ID);

  -- профилактика дубликатов оценок (зачтено)
  DELETE decanet.acad
    FROM (SELECT A.ACAD_ID, A.PERSPROG_ID, A.document_ID, X.CNT
            FROM (SELECT MAX(ACAD_ID) AS ACAD_ID, COUNT(ACAD_ID) AS CNT
                    FROM ACAD
                    WHERE RESULT_ID = 5
                    GROUP BY PERSPROG_ID HAVING COUNT(ACAD_ID) > 1) X LEFT JOIN
                 decanet.acad A USING (ACAD_ID)) Y LEFT JOIN
         decanet.acad USING (ACAD_ID);

END $$

