-- модификация с 0.011 до 0.012
DROP PROCEDURE IF EXISTS decanet.DCVERS_0011_0012 $$
CREATE PROCEDURE decanet.DCVERS_0011_0012()
BEGIN
  -- Машков
  UPDATE decanet.persprog
    SET STUDSGRP_ID = 2556
    WHERE STUDSGRP_ID = 2046;

  CALL decanet.NEWMAINPROGSYNC(2556);

  -- имена групп на ГФ УГЛТУ
  UPDATE decanet.division
    SET DIVISION_ALGNO = 1
    WHERE FACULTET_ID = 3;


END $$

-- модификация с 0.012 до 0.013
DROP PROCEDURE IF EXISTS decanet.DCVERS_0012_0013 $$
CREATE PROCEDURE decanet.DCVERS_0012_0013()
BEGIN

  -- удалить пустые акадоки
  DELETE decanet.document
    FROM decanet.document LEFT JOIN
         decanet.progdoc USING (DOCUMENT_ID)
    WHERE DOCUMENT_ID IS NULL AND
          DOCTYPE_ID IN (1,2,6,8,12);

  -- развести сильнопересекающиеся экспортные номера акадоков
  CREATE TEMPORARY TABLE decanet.ttDOCNO AS
    SELECT DOCUMENT_NO
      FROM document
      WHERE DOCTYPE_ID IN (1,2,6,8,12)
      GROUP BY DOCUMENT_NO HAVING COUNT(DOCUMENT_NO) > 2;

  UPDATE decanet.ttDOCNO T LEFT JOIN
         decanet.document D USING (DOCUMENT_NO)
    SET D.document_NO = D.document_BARNO;

END $$

