-- модификация с 0.015 до 0.016
DROP PROCEDURE IF EXISTS decanet.DCVERS_0015_0016 $$
CREATE PROCEDURE decanet.DCVERS_0015_0016()
BEGIN
 DROP TABLE IF EXISTS decanet.ttSTUDRESCNT;

 -- ТЮИ
 UPDATE decanet.school
   SET SCHOOL_NAME = 'ГОУ ВПО "Тюменский юридический институт МВД России"'
   WHERE SCHOOL_ID = 2;

 UPDATE decanet.division
   SET DIVISION_ABBR = '030501.65',
       DIVISION_NAME = '030501.65 Юриспруденция'
   WHERE DIVISION_ID = 10;

 UPDATE decanet.division
   SET DIVISION_ABBR = '030505.65',
       DIVISION_NAME = '030505.65 Правоохранительная деятельность'
   WHERE DIVISION_ID = 11;

/*
  -- порядок в документах !!! СЛИТЬ С РАБОТЫ !!!
  UPDATE
    (SELECT *, COUNT(DOCUMENT_ID)
       FROM decanet.document
       GROUP BY DOCTYPE_ID, FACULTET_ID, DOCUMENT_NO HAVING COUNT(DOCUMENT_ID) > 1) X LEFT JOIN
    decanet.document D USING (DOCUMENT_ID)
  SET D.document_NO = CONCAT(D.document_NO, '(1)');

  UPDATE
    (SELECT *, COUNT(DOCUMENT_ID)
       FROM decanet.document
       GROUP BY DOCTYPE_ID, FACULTET_ID, DOCUMENT_NO HAVING COUNT(DOCUMENT_ID) > 1) X LEFT JOIN
    decanet.document D USING (DOCUMENT_ID)
  SET D.document_NO = CONCAT(D.document_NO, '(2)');
*/

  -- порядок в документах
  SET @n = 0;
  SET @d = '';

  DROP TEMPORARY TABLE IF EXISTS decanet.ttDOCNO;
  CREATE TEMPORARY TABLE decanet.ttDOCNO AS
  SELECT D.document_ID, IF(NOT (@d <=> D.document_NO), @n:= 0, NULL) AS A,
              IF(NOT (@d <=> D.document_NO), @d:= D.document_NO, NULL) AS B,
              CONCAT(TRIM(D.document_NO), ' (', @n:= @n + 1, ')') AS C
    FROM
      (SELECT DOCTYPE_ID, FACULTET_ID, DOCUMENT_NO
         FROM decanet.document
         GROUP BY DOCTYPE_ID, FACULTET_ID, DOCUMENT_NO
           HAVING COUNT(DOCUMENT_ID) > 1) X LEFT JOIN
      decanet.document D USING (DOCTYPE_ID, FACULTET_ID, DOCUMENT_NO)
    ORDER BY DOCTYPE_ID, FACULTET_ID, DOCUMENT_NO;


  UPDATE
    decanet.ttDOCNO T LEFT JOIN
    decanet.document D USING (DOCUMENT_ID)
    SET D.document_NO = T.C;


  IF NOT INDEXEXISTS('UIDX_DOCUMENT', 'document') THEN
    CREATE UNIQUE INDEX UIDX_DOCUMENT ON decanet.document(DOCTYPE_ID, FACULTET_ID, DOCUMENT_NO);
  END IF;

  -- специализации ТЮИ
  INSERT INTO decanet.subspec(SUBSPEC_ID, GOSTITLE_ID, SUBSPEC_CODE, SUBSPEC_NAME)
    VALUES(NULL, 5, '030501.65', 'Уголовно-правовая');

  UPDATE decanet.division
    SET SUBSPEC_ID = Last_Insert_ID()
    WHERE DIVISION_ID = 10;

  INSERT INTO decanet.subspec(SUBSPEC_ID, GOSTITLE_ID, SUBSPEC_CODE, SUBSPEC_NAME)
    VALUES(NULL, 6, '030505.65', 'Уголовно-правовая');

  UPDATE decanet.division
    SET SUBSPEC_ID = Last_Insert_ID()
    WHERE DIVISION_ID = 11;

  -- реферат, практикум
  INSERT INTO decanet.control(CONTROL_ID, CONTROL_ENDFLAG, CONTROL_ABBR, CONTROL_NAME, CONTROL_NAMED)
    VALUES (16, 0, 'Реф', 'Реферат', 1),
           (17, 0, 'Пкум', 'Практикум', 1);

  INSERT INTO decanet.phasectrl(PHASECTRL_ID, SESSPHASE_ID, CONTROL_ID)
    VALUES (NULL, 2, 16),
           (NULL, 2, 17);

  -- группы видов контроля (для справки, карточки)
  CREATE TABLE decanet.ctrlgrp (CTRLGRP_ID INT NOT NULL AUTO_INCREMENT,
                                CONSTRAINT PK_CTRLGRP PRIMARY KEY (CTRLGRP_ID),
                                CTRLGRP_ABBR VARCHAR(25) NOT NULL,
                                CTRLGRP_NAME VARCHAR(255)
  ) /*!ENGINE=INNODB*/;

  IF NOT INDEXEXISTS('UIDX_CTRLGRP', 'ctrlgrp') THEN
    CREATE UNIQUE INDEX UIDX_CTRLGRP ON decanet.ctrlgrp(CTRLGRP_ABBR);
  END IF;

  INSERT INTO decanet.ctrlgrp(CTRLGRP_ID, CTRLGRP_ABBR, CTRLGRP_NAME)
    VALUES(1, 'ЗачЭкз', 'Зачёты и экзамены'),
          (2, 'Курс', 'Курсовые'),
          (3, 'Практ', 'Практики'),
          (4, 'Вып', 'Выпускные'),
          (5, 'Проч', 'Прочие');

  ALTER TABLE decanet.control ADD COLUMN CTRLGRP_ID INT NOT NULL AFTER CONTROL_ID;
  UPDATE decanet.control
    SET CTRLGRP_ID = CASE CONTROL_ID
                       WHEN 1 THEN 1
                       WHEN 2 THEN 1
                       WHEN 3 THEN 1
                       WHEN 4 THEN 2
                       WHEN 5 THEN 2
                       WHEN 6 THEN 3
                       WHEN 7 THEN 3
                       WHEN 8 THEN 3
                       WHEN 9 THEN 3
                       WHEN 10 THEN 5
                       WHEN 11 THEN 4
                       WHEN 12 THEN 4
                       WHEN 13 THEN 4
                       WHEN 14 THEN 5
                       WHEN 15 THEN 5
                       WHEN 16 THEN 5
                       WHEN 17 THEN 2
                     END;

  ALTER TABLE decanet.control ADD CONSTRAINT FK_CONTROL_CTRLGRP FOREIGN KEY (CTRLGRP_ID) REFERENCES ctrlgrp(CTRLGRP_ID) ON DELETE NO ACTION ON UPDATE NO ACTION;

END $$

-- модификация с 0.016 до 0.017
DROP PROCEDURE IF EXISTS decanet.DCVERS_0016_0017 $$
CREATE PROCEDURE decanet.DCVERS_0016_0017()
BEGIN
  DECLARE r INT DEFAULT 1;

  -- результаты реферат (CONTROL_ID = 16)
  INSERT INTO decanet.resset (RESSET_ID, CONTROL_ID, RESULT_ID)
    VALUES (NULL, 16, 1),
           (NULL, 16, 2),
           (NULL, 16, 3),
           (NULL, 16, 4),
  -- результаты практикум (CONTROL_ID = 17)
           (NULL, 17, 5),
           (NULL, 17, 6);

  -- рейтинг
  INSERT INTO decanet.control(CONTROL_ID, CTRLGRP_ID, CONTROL_ENDFLAG, CONTROL_ABBR, CONTROL_NAME, CONTROL_NAMED)
    VALUES (18, 5, 0, 'Рейт', 'Рейтинг %', 0);

  INSERT INTO decanet.phasectrl(PHASECTRL_ID, SESSPHASE_ID, CONTROL_ID)
    VALUES (NULL, 1, 18);

  WHILE r <= 100 DO
    -- процентные результаты
    INSERT INTO decanet.result(RESULT_ID, RESULT_INT, RESULT_ABBR, RESULT_NAME, RESULT_PASSFLAG)
      VALUES (r + 6, r, CONCAT(r, '%'), CONCAT(r, '%'), IF(r <= 50, 0, 1));

    -- результаты рейтинг (CONTROL_ID = 18)
    INSERT INTO decanet.resset (RESSET_ID, CONTROL_ID, RESULT_ID)
      VALUES (NULL, 18, r + 6);

    SET r = r + 1;
  END WHILE;

  -- дата до (например акад.отпуск)
  ALTER TABLE decanet.contingent ADD COLUMN CONTINGENT_TODATE DATE AFTER CONTINGENT_DATE;

END $$


