-- модификация с 0.018 до 0.019
DROP PROCEDURE IF EXISTS decanet.DCVERS_0018_0019 $$
CREATE PROCEDURE decanet.DCVERS_0018_0019()
BEGIN


  -- переименование факультета ID = 1 в Институтом леса и природопользования ИЛП
  UPDATE decanet.facultet
    SET FACULTET_ABBR = 'ИЛП',
        FACULTET_NAME = 'Институт леса и природопользования'
    WHERE FACULTET_ID = 1;

  -- декан ЛХФ -> Директор ИЛП
  INSERT INTO decanet.perstatus(PERSTATUS_ID, PERSTATUS_NAME)
    VALUES(4, 'Директор');
  
  UPDATE decanet.person SET PERSTATUS_ID = 4 WHERE PERSON_ID = 2;

  -- уникальность номера документа - в течении года 
  ALTER TABLE decanet.document DROP INDEX UIDX_DOCUMENT;
  ALTER TABLE decanet.document ADD COLUMN DOCUMENT_PERIOD INT NOT NULL DEFAULT 0 AFTER DOCUMENT_EXPIRE;
  UPDATE decanet.document
    SET DOCUMENT_PERIOD = CAST(YEAR(DOCUMENT_OUTDATE) AS SIGNED);

  IF NOT INDEXEXISTS('UIDX_DOCUMENT', 'document') THEN
    CREATE UNIQUE INDEX UIDX_DOCUMENT ON decanet.document(DOCTYPE_ID, FACULTET_ID, DOCUMENT_NO, DOCUMENT_PERIOD);
  END IF;

--  CREATE TRIGGER ins_document BEFORE INSERT ON decanet.document
--   FOR EACH ROW
--     SET NEW.document_PERIOD := CAST(YEAR(NOW()) AS SIGNED);

  -- уникальность личного номера студента - в течении года
  ALTER TABLE decanet.student DROP INDEX UIDX_STUDENT;
  ALTER TABLE decanet.student ADD COLUMN STUDENT_PERIOD INT NOT NULL DEFAULT 0 AFTER STUDENT_PERSNO;
  UPDATE decanet.student S LEFT JOIN
         decanet.studsgrp SG USING (STUDENT_ID) LEFT JOIN
         decanet.sgroup G USING (SGROUP_ID) LEFT JOIN
         decanet.stream M USING (STREAM_ID)
    SET S.student_PERIOD = CAST(M.STREAM_FROMYEAR AS SIGNED);

  IF NOT INDEXEXISTS('UIDX_STUDENT', 'student') THEN
    CREATE UNIQUE INDEX UIDX_STUDENT ON decanet.student(STUDENT_PERSNO, STUDENT_PERIOD);
  END IF;

--  CREATE TRIGGER ins_student BEFORE INSERT ON decanet.student
--   FOR EACH ROW 
--     SET NEW.student_PERIOD := CAST(YEAR(NOW()) AS SIGNED);


  -- очередное добавление отделений
  -- опять пока с ГОСом = 1
  -- откуда взялся DIVISION_ID = 33 ???

  INSERT INTO decanet.division (DIVISION_ID, FACULTET_ID, GOSTITLE_ID, EDUTYPE_ID, SUBSPEC_ID, DIVISION_ABBR, DIVISION_NAME, DIVISION_UYEAR, DIVISION_HALFUYEAR, DIVISION_NPREFIX, DIVISION_ALGNO)
    VALUES (34, 1, 1,  3, NULL, '2501001.62', '2501001.62 Лесное хозяйство', 9, 2, '', 1),
           (35, 1, 1,  3, NULL, '2501003.62', '2501003.62 Лесоустройство и лесоуправление', 9, 2, '', 1),
           (36, 1, 1,  3, NULL, '2501005.62', '2501005.62 Лесомелиорация ландшафтов и инженерная биология', 9, 2, '', 1),
           (37, 1, 1,  3, NULL, '2501001.62 (3г)', '2501001.62 Лесное хозяйство', 9, 2, '', 1),
           (38, 1, 1,  3, NULL, '2501003.62 (3г)', '2501003.62 Лесоустройство и лесоуправление', 9, 2, '', 1),           
           (39, 1, 1,  3, NULL, '2501005.62 (3г)', '2501005.62 Лесомелиорация ландшафтов и инженерная биология', 9, 2, '', 1),
	   (40, 1, 1,  3, NULL, '110500.62', '110500.62 Садоводство', 9, 2, '', 1),
	   (41, 1, 1,  3, NULL, '280100.62', '280100.62 Природообустройство и водопользование', 9, 2, '', 1),
	   (42, 1, 1,  4, NULL, '022000.62', '280100.62 Экология и природопользование', 9, 2, '', 1),
	   (43, 1, 1,  3, NULL, '110119.51', '110119.51 Флористика (СПО колледж)', 9, 2, '', 1);

END $$

-- модификация с 0.019 до 0.020
DROP PROCEDURE IF EXISTS decanet.DCVERS_0019_0020 $$
CREATE PROCEDURE decanet.DCVERS_0019_0020()
BEGIN

  -- перенос 12 и 13 отделений с ГФ на ИЛП
  UPDATE decanet.division
    SET FACULTET_ID = 1,
        DIVISION_ABBR = '43.03.01 Бакалавриат',
        DIVISION_NAME = '43.03.01 Конгрессно-выставочный сервис'
    WHERE DIVISION_ID = 12;

  UPDATE decanet.division
    SET FACULTET_ID = 1,
        DIVISION_ABBR = '43.03.02 Бакалавриат',
        DIVISION_NAME = '43.03.02 Туризм'
    WHERE DIVISION_ID = 13;


END $$

-- модификация с 0.020 до 0.021
DROP PROCEDURE IF EXISTS decanet.DCVERS_0020_0021 $$
CREATE PROCEDURE decanet.DCVERS_0020_0021()
BEGIN

  -- добавление секретного ключа для 2FA
  ALTER TABLE decanet.duser ADD COLUMN DUSER_2FA varchar(255) DEFAULT NULL AFTER BUPASS;   

  -- устранение конфликта studsgrp.DIVISION_ID

  DROP TEMPORARY TABLE IF EXISTS ttt_slist;
  CREATE TEMPORARY TABLE ttt_slist AS
    SELECT STUDENT_ID, COUNT(DIVISION_ID) AS DIVCNT
      FROM decanet.studsgrp
      GROUP BY STUDENT_ID HAVING COUNT(DIVISION_ID) > 1;

   DROP TEMPORARY TABLE IF EXISTS ttt_divconf;
   CREATE TEMPORARY TABLE ttt_divconf AS
     SELECT SSG.*, R.DIVISION_ID AS DIVCONFL
     FROM ttt_slist LEFT JOIN
          decanet.studsgrp SSG USING (STUDENT_ID) LEFT JOIN
          decanet.sgroup G USING (SGROUP_ID) LEFT JOIN
          decanet.stream R USING (STREAM_ID)
     WHERE SSG.DIVISION_ID<>R.DIVISION_ID;

   DROP TEMPORARY TABLE IF EXISTS ttt_divstud;
   CREATE TEMPORARY TABLE ttt_divstud AS
     SELECT SSG.*
     FROM ttt_divconf LEFT JOIN
          decanet.studsgrp SSG USING (STUDENT_ID);

   DROP TEMPORARY TABLE IF EXISTS ttt_studdel;
   CREATE TEMPORARY TABLE ttt_studdel AS
     SELECT SSG.*
     FROM decanet.ttt_divstud LEFT JOIN
          decanet.studsgrp SSG USING (STUDSGRP_ID) LEFT JOIN
          decanet.contingent USING (STUDSGRP_ID)
     WHERE CONTINGENT_ID IS NULL;

   DELETE decanet.contingent
     FROM decanet.ttt_studdel LEFT JOIN
          decanet.contingent USING (STUDSGRP_ID);

   DELETE decanet.acad
     FROM decanet.ttt_studdel LEFT JOIN
          decanet.persprog USING (STUDSGRP_ID) LEFT JOIN
          decanet.acad USING (PERSPROG_ID);

   DELETE decanet.progdoc
     FROM decanet.ttt_studdel LEFT JOIN
          decanet.persprog USING (STUDSGRP_ID) LEFT JOIN
          decanet.progdoc USING (PERSPROG_ID);

   DELETE decanet.persprog
     FROM decanet.ttt_studdel LEFT JOIN
          decanet.persprog USING (STUDSGRP_ID);

   DELETE decanet.studdoc
     FROM decanet.ttt_studdel LEFT JOIN
          decanet.studdoc USING (STUDSGRP_ID);

   DELETE decanet.studsgrp
     FROM decanet.ttt_studdel LEFT JOIN
          decanet.studsgrp USING (STUDSGRP_ID) LEFT JOIN
          decanet.contingent USING (STUDSGRP_ID)
     WHERE CONTINGENT_ID IS NULL;

   UPDATE
     decanet.division V LEFT JOIN
     decanet.stream R USING (DIVISION_ID) LEFT JOIN
     decanet.sgroup G USING (STREAM_ID) LEFT JOIN
     decanet.studsgrp SSG USING (SGROUP_ID) LEFT JOIN
     decanet.division V1 ON V1.DIVISION_ID = SSG.DIVISION_ID
     SET SSG.DIVISION_ID = R.DIVISION_ID
     WHERE V.DIVISION_ID <> V1.DIVISION_ID;

   ALTER TABLE decanet.acad       DROP COLUMN CRT_, DROP COLUMN CUSR_, DROP COLUMN UPD_, DROP COLUMN UUSR_;
   ALTER TABLE decanet.contingent DROP COLUMN CRT_, DROP COLUMN CUSR_, DROP COLUMN UPD_, DROP COLUMN UUSR_;
   ALTER TABLE decanet.document   DROP COLUMN CRT_, DROP COLUMN CUSR_, DROP COLUMN UPD_, DROP COLUMN UUSR_;
   ALTER TABLE decanet.dsession   DROP COLUMN CRT_, DROP COLUMN CUSR_, DROP COLUMN UPD_, DROP COLUMN UUSR_;
   ALTER TABLE decanet.mainprog   DROP COLUMN CRT_, DROP COLUMN CUSR_, DROP COLUMN UPD_, DROP COLUMN UUSR_;
   ALTER TABLE decanet.mprogsubj  DROP COLUMN CRT_, DROP COLUMN CUSR_, DROP COLUMN UPD_, DROP COLUMN UUSR_;
   ALTER TABLE decanet.persname   DROP COLUMN CRT_, DROP COLUMN CUSR_, DROP COLUMN UPD_, DROP COLUMN UUSR_;
   ALTER TABLE decanet.persprog   DROP COLUMN CRT_, DROP COLUMN CUSR_, DROP COLUMN UPD_, DROP COLUMN UUSR_;
   ALTER TABLE decanet.prolong    DROP COLUMN CRT_, DROP COLUMN CUSR_, DROP COLUMN UPD_, DROP COLUMN UUSR_;
   ALTER TABLE decanet.sgroup     DROP COLUMN CRT_, DROP COLUMN CUSR_, DROP COLUMN UPD_, DROP COLUMN UUSR_;
   ALTER TABLE decanet.stipend    DROP COLUMN CRT_, DROP COLUMN CUSR_, DROP COLUMN UPD_, DROP COLUMN UUSR_;
   ALTER TABLE decanet.stream     DROP COLUMN CRT_, DROP COLUMN CUSR_, DROP COLUMN UPD_, DROP COLUMN UUSR_;
   ALTER TABLE decanet.studadd    DROP COLUMN CRT_, DROP COLUMN CUSR_, DROP COLUMN UPD_, DROP COLUMN UUSR_;
   ALTER TABLE decanet.student    DROP COLUMN CRT_, DROP COLUMN CUSR_, DROP COLUMN UPD_, DROP COLUMN UUSR_;
   ALTER TABLE decanet.subj       DROP COLUMN CRT_, DROP COLUMN CUSR_, DROP COLUMN UPD_, DROP COLUMN UUSR_;

   ALTER TABLE decanet.protocol   DROP COLUMN CRT_, DROP COLUMN CUSR_;

   UPDATE duser SET DUSER_MNAME='Александрович' WHERE DUNAME = 'sax' AND DUSER_ID=4;

END $$



